import { Component, OnDestroy, OnInit } from '@angular/core';
import { ReplaySubject } from 'rxjs';
import { GeneralService } from '../../services/general.service';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
@Component({
    selector: 'ocr-voucher-create',
    templateUrl: './ocr-voucher-create.component.html',
    styleUrls: ['./ocr-voucher-create.component.scss'],
    providers: []
})

export class OcrVoucherCreateComponent implements OnInit, OnDestroy {
    public dummy: any = {
        data: ""
    }
    /** This will use for hold table data */
    public inputData: any[] = [];
    /* This will hold local JSON data */
    public localeData: any = {};
    /* This will hold common JSON data */
    public commonLocaleData: any = {};
    /** Subject to unsubscribe from listeners */
    private destroyed$: ReplaySubject<boolean> = new ReplaySubject(1);
    /** PDF file url created with blob */
    public sanitizedPdfFileUrl: SafeUrl = null;
    /** Whether file is uploading */
    public isFileUploading: boolean = true;
    /** Holds PDF file value */
    public pdfFileURL: string = '';
    /** Holds Current selected invoice */
    public selectedVoucher: any;

    constructor(
        private domSanitizer: DomSanitizer,
        private generalService: GeneralService
    ) {
    }

    /**
     * Hook cycle for component initialization
     *
     * @memberof BuyPlanComponent
     */
    public ngOnInit(): void {
        let response = this.dummy;
        if (response) {
            this.selectedVoucher = this.generalService.base64ToBlob(response.data || response, 'application/pdf', 512);
            const file = new Blob([this.selectedVoucher], { type: 'application/pdf' });
            URL.revokeObjectURL(this.pdfFileURL);
            this.pdfFileURL = URL.createObjectURL(file);
            this.isFileUploading = false;
            this.sanitizedPdfFileUrl = this.domSanitizer.bypassSecurityTrustResourceUrl(this.pdfFileURL);
        } else {
            this.isFileUploading = false;

        }
    }

    /**
     * This will call on component destroy
     *
     * @memberof BuyPlanComponent
     */
    public ngOnDestroy(): void {
        this.destroyed$.next(true);
        this.destroyed$.complete();
    }
}
